    private void outline(){LinearLayout c=form();Switch toggle=new Switch(a);toggle.setText("显示区域与按钮描边");toggle.setTextSize(15);toggle.setChecked(prefs.getBoolean("outline",false));toggle.setOnCheckedChangeListener((v,on)->{prefs.edit().putBoolean("outline",on).apply();a.refreshScreen();});c.addView(toggle,a.lp(-1,54));a.gap(c,10);action(c,"设置描边颜色",this::colors);c.addView(a.text("描边：默认关闭。支持预设颜色及 #RRGGBB 自定义颜色。",13,a.MUTED,false));dialog("描边",c);}
    private void colors(){String[] labels=Arrays.copyOf(COLOR_NAMES,COLOR_NAMES.length+1);labels[labels.length-1]="自定义十六进制颜色";int current=COLORS.length;for(int n=0;n<COLORS.length;n++)if(a.outlineColor()==COLORS[n])current=n;new ToolDialog(a).setTitle("描边颜色").setSingleChoiceItems(labels,current,(x,n)->{if(n<COLORS.length){prefs.edit().putInt("outline_color",COLORS[n]).apply();a.refreshScreen();}else customColor(()->((AlertDialog)x).getListView().setItemChecked(COLORS.length,true));}).setNegativeButton("返回",null).show();}
    private void customColor(Runnable changed){EditText input=new EditText(a);input.setSingleLine(true);input.setHint("#000000");input.setText(String.format(Locale.ROOT,"#%06X",a.outlineColor()&0xffffff));input.setSelectAllOnFocus(true);AlertDialog d=new ToolDialog(a).setTitle("输入 #RRGGBB 颜色").setView(input).setPositiveButton("保存",null).setNegativeButton("返回",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(b->{String s=input.getText().toString().trim();if(!s.matches("#[0-9a-fA-F]{6}")){a.toast("请输入以 # 开头的六位十六进制颜色值，例如 #000000");return;}prefs.edit().putInt("outline_color",Color.parseColor(s)).apply();a.refreshScreen();changed.run();a.toast("描边颜色已保存");}));d.show();}
