    private void chooseRole(int role){String[] names={"红色","橙色","黄色","绿色","青色","蓝色（默认）","紫色","黑色","白色","自定义十六进制颜色"};int[] values={0xFFD64545,0xFFE48321,0xFFD39B16,0xFF2E8B57,0xFF168C9A,0xFF246BCE,0xFF7852A8,Color.BLACK,Color.WHITE};String key=ROLE_KEYS[role];int current=5;int saved=prefs.getInt(key,ROLE_DEFAULTS[role]);for(int i=0;i<values.length;i++)if(saved==values[i])current=i;new ToolDialog(a).setTitle(ROLE_NAMES[role]).setSingleChoiceItems(names,current,(d,n)->{if(n<values.length){prefs.edit().putInt(key,values[n]).apply();a.refreshScreen();}else roleCustom(role);}).setNegativeButton("返回",null).show();}
    private void roleCustom(int role){EditText input=new EditText(a);input.setSingleLine(true);input.setHint("#000000");input.setText(String.format(Locale.ROOT,"#%06X",prefs.getInt(ROLE_KEYS[role],ROLE_DEFAULTS[role])&0xffffff));AlertDialog d=new ToolDialog(a).setTitle("输入 #RRGGBB 颜色").setView(input).setPositiveButton("保存",null).setNegativeButton("返回",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(b->{String s=input.getText().toString().trim();try{if(!s.matches("#[0-9a-fA-F]{6}"))throw new IllegalArgumentException();prefs.edit().putInt(ROLE_KEYS[role],Color.parseColor(s)).apply();a.refreshScreen();d.dismiss();}catch(Exception ex){a.toast("请输入六位十六进制颜色，例如 #246BCE");}}));d.show();}
