    private void astronomyOrientation(){String[] labels={"外置相机方向（默认）","手机上沿方向"};int current=prefs.getString("astro_orientation_reference","camera").equals("top")?1:0;new ToolDialog(a).setTitle("对准天空方向").setMessage("对准天空使用旋转矢量传感器读取设备朝向，并在星图中心绘制红色实体十字。请选择用于表示朝向的设备方向。具体效果受设备传感器和系统坐标定义影响。此功能仅作观测辅助，不用于导航。").setSingleChoiceItems(labels,current,(d,n)->{prefs.edit().putString("astro_orientation_reference",n==0?"camera":"top").apply();a.refreshScreen();}).setNegativeButton("返回",null).show();}
